files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: #1a1a2e;
  color: #e0e0e0;
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: #16213e;
  border: 4px solid #0f3460;
  border-radius: 8px;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 0 0 4px #0f3460, 0 8px 24px rgba(0,0,0,0.5);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 16px;
  text-align: center;
  color: #e94560;
  text-transform: uppercase;
  letter-spacing: 2px;
}

.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

input[type="text"] {
  flex: 1;
  padding: 12px;
  font-size: 1rem;
  background: #1a1a2e;
  border: 2px solid #0f3460;
  border-radius: 4px;
  color: #e0e0e0;
  outline: none;
  transition: border-color 0.2s;
}

input[type="text"]:focus {
  border-color: #e94560;
}

button {
  padding: 12px 20px;
  font-size: 1rem;
  font-weight: bold;
  background: #e94560;
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

button:hover {
  background: #c73650;
}

button:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
  background: #a82a40;
}

.counts {
  display: flex;
  justify-content: space-between;
  font-size: 0.9rem;
  margin-bottom: 16px;
  color: #a0a0b0;
}

ul {
  list-style: none;
}

li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 2px solid #0f3460;
}

li:last-child {
  border-bottom: none;
}

li span {
  flex: 1;
  word-break: break-word;
}

li input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: #e94560;
  cursor: pointer;
}

li button {
  padding: 6px 12px;
  font-size: 0.85rem;
  background: #0f3460;
}

li button:hover {
  background: #e94560;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.2rem;
  }
}

let nextId = 1;
const tasks = [];

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');
const list = document.getElementById('todo-list');

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.completed).length;
}

function renderTask(task) {
  const li = document.createElement('li');
  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = `todo-check-${task.id}`;
  checkbox.checked = task.completed;
  checkbox.setAttribute('aria-label', `Mark task ${task.id} as ${task.completed ? 'incomplete' : 'complete'}`);
  checkbox.addEventListener('change', () => {
    task.completed = checkbox.checked;
    checkbox.setAttribute('aria-label', `Mark task ${task.id} as ${task.completed ? 'incomplete' : 'complete'}`);
    updateCounts();
  });

  const span = document.createElement('span');
  span.id = `todo-text-${task.id}`;
  span.textContent = task.text;

  const delBtn = document.createElement('button');
  delBtn.id = `todo-delete-${task.id}`;
  delBtn.textContent = 'Delete';
  delBtn.setAttribute('aria-label', `Delete task ${task.id}`);
  delBtn.addEventListener('click', () => {
    const idx = tasks.indexOf(task);
    if (idx > -1) tasks.splice(idx, 1);
    li.remove();
    updateCounts();
  });

  li.append(checkbox, span, delBtn);
  list.appendChild(li);
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const task = { id: nextId++, text, completed: false };
  tasks.push(task);
  renderTask(task);
  updateCounts();
  input.value = '';
  input.focus();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') addTask();
});

updateCounts();
